  ["Lists the boss mods DMGAssist detected: DBM, BigWigs or LittleWigs."] = "DMGAssist가 DBM, BigWigs, LittleWigs 중 무엇을 읽고 있는지 보여 줍니다.",
  ["Profile"] = "프로필",
